"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78839"],{9074(e){e.exports=JSON.parse('{"id":"FIN-357","slug":"bank-run","term":"Bank Run","also_known_as":[],"difficulty":"Beginner","definition":"A bank run happens when large numbers of customers withdraw their deposits at the same time because they fear the bank may fail.","explanation":["Banks keep only a small portion of deposits as cash and lend out the rest. Under normal conditions, this works because only a few customers withdraw money on any given day. But if many depositors believe the bank is in trouble and try to withdraw at once, the bank may not have enough cash available.","Bank runs can become self-fulfilling. Even a healthy bank can be pushed into failure if enough people panic, because it may have to sell assets quickly at low prices to raise cash. Fear spreads as people see others withdrawing, encouraging still more withdrawals.","Today, runs can happen very quickly, because customers can move money instantly through online and mobile banking, and news and rumours spread rapidly on social media.","To prevent runs, governments use deposit insurance, which reassures customers that their money is protected up to a limit. Central banks can act as a lender of last resort, providing emergency funding to banks facing sudden withdrawals. Regulators also require banks to hold enough liquid assets and capital to withstand stress."],"note":"","total":1500,"prev":{"slug":"bank-resolution","term":"Bank Resolution"},"next":{"slug":"bank-transfer","term":"Bank Transfer"}}')}}]);